#include <bits/stdc++.h>
using namespace std;

class FastReader {
public:
    std::istream& in;
    std::string buffer;
    std::istringstream iss;

    FastReader() : in(std::cin) {}

    std::string next() {
        while (!(iss >> buffer)) {
            std::getline(in, buffer);
            iss.clear();
            iss.str(buffer);
        }
        return buffer;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }
};

int main() {
    FastReader inputReader;
    std::ostream& outputWriter = std::cout;

    long long MOD = 1000000007;
    int n = inputReader.nextInt();

    std::vector<long long> currentDP(2 * n + 1, 0);
    long long totalCount = 0;
    currentDP[0] = 1;

    for (int p = 1; p <= 2 * n; p++) {
        std::vector<long long> nextDP(2 * n + 1, 0);
        for (int i = 0; i < 2 * n; i++) {
            nextDP[i + 1] = (nextDP[i + 1] + currentDP[i]) % MOD;
            if (i - 1 >= 0) {
                nextDP[i - 1] = (nextDP[i - 1] + currentDP[i]) % MOD;
                if (p % 2 == 0) {
                    int r = 2 * n - p;
                    if (r >= i - 1) {
                        totalCount = (totalCount + currentDP[i]) % MOD;
                    }
                }
            }
        }
        currentDP = nextDP;
    }

    outputWriter << totalCount << "\n";

    return 0;
}
